### Issue description

When implementing a CompositorEffect in C# (and only in C#. GdScript works fine.) I have encountered the following issue:
- Implement the CompositorEffect like recommended by the documentation: [https://docs.godotengine.org/en/stable/tutorials/rendering/compositor.html](url)
- When assembling and later on executing the following errors will repeat every frame: 

<img width="1410" height="80" alt="Image" src="https://github.com/user-attachments/assets/e30a62cf-863b-419e-82e8-d8dc1dc2b5d0" />

The script that produces implements the Effect: 

```
using Godot;

[Tool]
[GlobalClass]
public partial class CompositorEffectBase : CompositorEffect
{
    [Export] private RDShaderFile shaderFile;

    Rid shaderRid = new Rid();
    Rid pipelineRid = new Rid();
    Mutex mutex = new();


    #region Render Thread Code
    public override void _RenderCallback(int effectCallbackType, RenderData renderData)
    {
        base._RenderCallback(effectCallbackType, renderData);

        if(!pipelineRid.IsValid){
            CreateShader();
        }

        GD.Print(pipelineRid.IsValid);
        if(effectCallbackType == (int)EffectCallbackTypeEnum.PostTransparent && pipelineRid.IsValid){
            // Get our render scene buffers object, this gives us access to our render buffers.
		    // Note that implementation differs per renderer hence the need for the cast.

		    var renderSceneBuffers = renderData.GetRenderSceneBuffers() as RenderSceneBuffersRD;
		    if (renderSceneBuffers != null) {
		    	// Get our render size, this is the 3D render resolution!
		    	var size = renderSceneBuffers.GetInternalSize();
		    	if (size.X == 0 && size.Y == 0){
		    		return;
                }

                Vector3 invokeGroups = new Vector3(
                    ((size.X - 1) / 16) + 1, 
                    ((size.X - 1) / 16) + 1, 
                    1);


		    	// Loop through views just in case we're doing stereo rendering. No extra cost if this is mono.
		    	uint viewCount = renderSceneBuffers.GetViewCount();
                Rid colorTextureRid = renderSceneBuffers.GetColorTexture();
		    	for(uint i = 0; i < viewCount; i++){
                    GD.Print($"ShaderRid: {shaderRid}");
                    GD.Print($"PipelineRid: {pipelineRid}");

                    //var imageRid = screenTextureWriteCopy;
                    var imageRid = renderSceneBuffers.GetColorLayer(i);
                    GD.Print($"ImageRid: {imageRid}");

		    		// Create a uniform set, this will be cached, the cache will be cleared if our viewports configuration is changed.
		    		var uniform = new RDUniform();
		    		uniform.UniformType = RenderingDevice.UniformType.Image;
		    		uniform.Binding = 0;
		    		uniform.AddId(imageRid);

                    var uniformSet = RenderingServer.Singleton.GetRenderingDevice().UniformSetCreate(new ( new[] {uniform}), shaderRid, 0);

		    		// Run our compute shader.
                    var rd = RenderingServer.Singleton.GetRenderingDevice();
		    		var computeList = rd.ComputeListBegin();
		    		rd.ComputeListBindComputePipeline(computeList, pipelineRid);
		    		rd.ComputeListBindUniformSet(computeList, uniformSet, 0);
		    		rd.ComputeListDispatch(computeList, (uint)invokeGroups.X, (uint)invokeGroups.Y, (uint)invokeGroups.Z);
		    		rd.ComputeListEnd();
                }
            }
        }
    }


    protected void CreateShader(){
        RDShaderSpirV spirv;
        mutex.Lock();
        if(shaderFile.BaseError != ""){
            GD.PrintErr(shaderFile.BaseError);
            return;
        }

        spirv = shaderFile.GetSpirV();
        mutex.Unlock();

        if(spirv.CompileErrorCompute != ""){
            GD.PrintErr(spirv.CompileErrorCompute);
            return;
        }

        shaderRid = RenderingServer.Singleton.GetRenderingDevice().ShaderCreateFromSpirV(spirv);
        if(!shaderRid.IsValid){
            GD.PrintErr("Shader Rid not valid");
            return;
        }

        pipelineRid = RenderingServer.Singleton.GetRenderingDevice().ComputePipelineCreate(shaderRid);
    }

    #endregion


    public override void _Notification(int what)
    {
        base._Notification(what);
        if(what == NotificationPredelete){
            if(shaderRid.IsValid){
                RenderingServer.Singleton.FreeRid(shaderRid);
            }
        } 
    }
}
```



The test shader to be used:

```
#[compute]
#version 450

layout(local_size_x = 8, local_size_y = 8, local_size_z = 1) in;

layout(rgba16f, set = 0, binding = 0) uniform image2D color_image;

void main() {
	ivec2 uv = ivec2(gl_GlobalInvocationID.xy);
	ivec2 size = imageSize(color_image);
	if (uv.x >= size.x || uv.y >= size.y) {
		return;
	}

	vec4 color = imageLoad(color_image, uv);
	float gray = color.r * 0.2125 + color.g * 0.7154 + color.b * 0.0721;
	color.rgb = vec3(gray);

	imageStore(color_image, uv, color);
}
```

To assemble: Create a CompositorEffectBase in an arbitrary Compositor and attach the shader code as a "Test.glsl" File. Make sure it is an RDShaderFile. When entering a scene the error produces.


### Steps to reproduce

In the provided project run the "node_3d.tscn" scene. The error should produce.

